<script module lang="ts">
/**
 * Search and filters with a clear button and result count (`design/components/filter-bar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/filter-bar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/filter-bar.module.css'
import Button from '../controls/Button.svelte'
import Inline from '../layout/Inline.svelte'

export interface FilterResultCount {
  shown: number
  total?: number
}

export interface FilterBarMessages {
  clear: string
  resultCount: (count: FilterResultCount) => string
}

export interface FilterBarProps {
  /**
   * Filter controls, each an `sm` `Select` with an `emptyOption`.
   */
  children?: Snippet
  /**
   * The only input that shows or hides the clear button.
   */
  isFiltered: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: FilterBarMessages
  onClear?: () => void
  resultCount?: FilterResultCount
  /**
   * A `SearchInput`, `sm` by convention.
   */
  search?: Snippet
}
</script>

<script lang="ts">
let {
  children,
  isFiltered,
  messages = (() => ({
    clear: 'Clear filters',
    resultCount: ({ shown, total }: FilterResultCount) =>
      total === undefined ? `${shown} results` : `${shown} of ${total} results`,
  }))(),
  onClear,
  resultCount,
  search,
}: FilterBarProps = $props()
const joined = joinSlot(undefined, () => ({}))
let clearRegion = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'FilterBar',
    element: () => root,
    state: () => ({
      filtered: isFiltered,
      'result-count': resultCount === undefined ? '' : messages.resultCount(resultCount),
    }),
    actions: {
      clear: () =>
        (() => {
          if (!isFiltered) throw new Error('Nothing is filtered, so there is nothing to clear.')
          onClear?.()
        })(),
    },
    withholds: () => clearRegion,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.bar}
    data-filtered={(isFiltered) ? '' : undefined}
    data-member="filter-bar"
    ><Inline gap={3} align="center" wrap={true}
      >{@render search?.()
      }{@render children?.()
      }{#if isFiltered
        }<span bind:this={clearRegion} class={styles.clear}
          ><Button
            variant="ghost"
            tone="neutral"
            size="sm"
            icon="clear"
            label={messages.clear}
            onClick={() => { onClear?.() }}
        /></span
      >{/if
      }{#if resultCount !== undefined
        }<span class={styles.count} aria-live="polite">{messages.resultCount(resultCount)}</span
      >{/if
    }</Inline
  ></div
>{/if
}{@render joined.end?.()}
